import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import {
  Activity as ActivityIcon,
  Check,
  ChevronRight,
  CircleAlert,
  Clock3,
  FileText,
  Inbox as InboxIcon,
  LayoutDashboard,
  LockKeyhole,
  Mail,
  Menu,
  MoreHorizontal,
  Pause,
  Play,
  Plus,
  RotateCcw,
  Send,
  Settings2,
  ShieldCheck,
  Sparkles,
  Trash2,
  Users,
  X,
} from "lucide-react";
import { ApiError, apiDelete, apiGet, apiPatch, apiPost } from "@/lib/api";
import type {
  Activity,
  Campaign,
  CsvCampaign,
  CsvSourceSummary,
  HistoryEntry,
  Inbox,
  LaunchResponse,
  Overview,
  Recipient,
  ScheduledEmail,
  Template,
} from "@/lib/types";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Toaster } from "@/components/ui/sonner";

type View = "dashboard" | "campaigns" | "recipients" | "inboxes" | "imports" | "templates" | "history" | "settings";
type DeleteTarget = { resource: "inboxes" | "recipients" | "templates" | "campaigns"; id: string; label: string };

const emptyOverview: Overview = {
  sent_today: 0,
  queued: 0,
  error_rate: 0,
  active_inboxes: 0,
  active_campaigns: 0,
  next_send_at: null,
  next_send_in_minutes: null,
  recent_activity: [],
};

const formatDate = (value: string | null) =>
  value
    ? new Intl.DateTimeFormat("en", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }).format(new Date(value))
    : "—";

const initials = (value: string) => value.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase();

const mutationErrorMessage = (error: unknown) => {
  if (error instanceof ApiError) {
    const body = error.body as { detail?: unknown } | null;
    return typeof body?.detail === "string" ? body.detail : `Request failed (${error.status})`;
  }
  return "Request failed. Please try again.";
};

function StatusBadge({ status }: { status: string }) {
  const tone = status === "active" || status === "connected" || status === "sent"
    ? "bg-emerald-50 text-emerald-700"
    : status === "failed" || status === "error"
      ? "bg-red-50 text-red-700"
      : "bg-amber-50 text-amber-700";
  return <span data-testid={`status-badge-${status}`} className={`inline-flex items-center gap-1.5 rounded-md px-2 py-1 text-[11px] font-medium capitalize ${tone}`}><span className="size-1.5 rounded-full bg-current" />{status}</span>;
}

function PageTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="mb-6 flex flex-wrap items-end justify-between gap-4" data-testid="page-title-block">
    <div><p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.12em] text-zinc-500" data-testid="page-eyebrow">{eyebrow}</p><h1 className="font-heading text-3xl font-semibold tracking-tight text-zinc-950" data-testid="page-title">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-zinc-500" data-testid="page-description">{description}</p></div>
    {action}
  </div>;
}

function MetricCard({ label, value, detail, icon, accent }: { label: string; value: string; detail: string; icon: ReactNode; accent?: string }) {
  return <div className="border border-zinc-200 bg-white p-4" data-testid={`metric-card-${label.toLowerCase().replaceAll(" ", "-")}`}><div className="flex items-start justify-between"><p className="text-[11px] font-semibold uppercase tracking-[0.1em] text-zinc-500" data-testid="metric-label">{label}</p><span className={`flex size-8 items-center justify-center rounded-md ${accent ?? "bg-zinc-100 text-zinc-700"}`} data-testid="metric-icon">{icon}</span></div><p className="mt-5 font-heading text-3xl font-semibold tracking-tight text-zinc-950" data-testid="metric-value">{value}</p><p className="mt-1 text-xs text-zinc-500" data-testid="metric-detail">{detail}</p></div>;
}

function EmptyState({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) {
  return <div className="flex min-h-44 flex-col items-center justify-center border border-dashed border-zinc-300 bg-zinc-50 px-6 text-center" data-testid="empty-state"><div className="mb-3 flex size-10 items-center justify-center rounded-md border border-zinc-200 bg-white text-zinc-500"><Sparkles size={17} /></div><p className="text-sm font-medium text-zinc-800" data-testid="empty-state-title">{title}</p><p className="mt-1 max-w-sm text-xs leading-relaxed text-zinc-500" data-testid="empty-state-description">{description}</p>{action}</div>;
}

export default function Home() {
  const [view, setView] = useState<View>("dashboard");
  const [mobileNav, setMobileNav] = useState(false);
  const [showComposer, setShowComposer] = useState(false);
  const [showInboxForm, setShowInboxForm] = useState(false);
  const [showRecipientForm, setShowRecipientForm] = useState(false);
  const [showTemplateForm, setShowTemplateForm] = useState(false);
  const [editingInbox, setEditingInbox] = useState<Inbox | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<DeleteTarget | null>(null);
  const [settingsMinGap, setSettingsMinGap] = useState("10");
  const [settingsMaxGap, setSettingsMaxGap] = useState("20");
  const [activityCampaign, setActivityCampaign] = useState<CsvCampaign | null>(null);
  const queryClient = useQueryClient();
  const dashboardQuery = useQuery({ queryKey: ["dashboard"], queryFn: () => apiGet<Overview>("/workspace/dashboard"), retry: false });
  const inboxesQuery = useQuery({ queryKey: ["inboxes"], queryFn: () => apiGet<Inbox[]>("/workspace/inboxes"), retry: false });
  const recipientsQuery = useQuery({ queryKey: ["recipients"], queryFn: () => apiGet<Recipient[]>("/workspace/recipients"), retry: false });
  const templatesQuery = useQuery({ queryKey: ["templates"], queryFn: () => apiGet<Template[]>("/workspace/templates"), retry: false });
  const campaignsQuery = useQuery({ queryKey: ["campaigns"], queryFn: () => apiGet<Campaign[]>("/workspace/campaigns"), retry: false });
  const csvCampaignsQuery = useQuery({ queryKey: ["csv-campaigns"], queryFn: () => apiGet<CsvCampaign[]>("/csv/campaigns"), retry: false });
  const csvSourcesQuery = useQuery({ queryKey: ["csv-sources"], queryFn: () => apiGet<CsvSourceSummary[]>("/csv/sources"), retry: false });
  const historyQuery = useQuery({ queryKey: ["history"], queryFn: () => apiGet<HistoryEntry[]>("/workspace/history"), retry: false });
  const csvActivityQuery = useQuery({ queryKey: ["csv-campaign-activity", activityCampaign?.id], queryFn: () => apiGet<ScheduledEmail[]>(`/csv/campaigns/${activityCampaign?.id}/activity`), enabled: Boolean(activityCampaign) });
  const overview = dashboardQuery.data ?? emptyOverview;
  const inboxes = inboxesQuery.data ?? [];
  const recipients = recipientsQuery.data ?? [];
  const templates = templatesQuery.data ?? [];
  const campaigns = campaignsQuery.data ?? [];
  const csvCampaigns = csvCampaignsQuery.data ?? [];
  const csvSources = csvSourcesQuery.data ?? [];
  const history = historyQuery.data ?? [];
  const activeCampaign = campaigns.find((campaign) => campaign.status === "active") ?? campaigns[0];
  const gmailNotice = new URLSearchParams(window.location.search).get("gmail");

  const refresh = () => queryClient.invalidateQueries({ queryKey: ["dashboard"] });
  const connectMutation = useMutation({ mutationFn: (payload: { email: string; display_name: string }) => apiPost<Inbox>("/workspace/inboxes/connect", payload), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["inboxes"] }); refresh(); setShowInboxForm(false); toast.success("Preview inbox added"); }, onError: (error) => toast.error(mutationErrorMessage(error)) });
  const updateInboxMutation = useMutation({ mutationFn: ({ id, display_name, signature, daily_sending_limit }: { id: string; display_name: string; signature: string; daily_sending_limit: number }) => apiPatch<Inbox>(`/workspace/inboxes/${id}`, { display_name, signature, daily_sending_limit, status: "connected" }), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["inboxes"] }); setEditingInbox(null); toast.success("Inbox settings saved"); }, onError: (error) => toast.error(mutationErrorMessage(error)) });
  const recipientMutation = useMutation({ mutationFn: (payload: { name: string; email: string; company: string }) => apiPost<Recipient>("/workspace/recipients", payload), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["recipients"] }); setShowRecipientForm(false); toast.success("Recipient added"); }, onError: (error) => toast.error(mutationErrorMessage(error)) });
  const templateMutation = useMutation({ mutationFn: (payload: { name: string; subject: string; body: string }) => apiPost<Template>("/workspace/templates", payload), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["templates"] }); setShowTemplateForm(false); toast.success("Template saved"); }, onError: (error) => toast.error(mutationErrorMessage(error)) });
  const campaignMutation = useMutation({ mutationFn: (payload: { name: string; inbox_id: string; template_id: string; recipient_ids: string[]; min_gap_minutes: number; max_gap_minutes: number }) => apiPost<Campaign>("/workspace/campaigns", payload), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["campaigns"] }); refresh(); setShowComposer(false); toast.success("Campaign queued"); }, onError: (error) => toast.error(mutationErrorMessage(error)) });
  const launchMutation = useMutation({ mutationFn: (id: string) => apiPost<LaunchResponse>(`/workspace/campaigns/${id}/launch`), onSuccess: (result) => { queryClient.invalidateQueries({ queryKey: ["campaigns"] }); queryClient.invalidateQueries({ queryKey: ["history"] }); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); toast.success(result.is_mocked ? "Campaign launched — MOCKED first send recorded" : "Campaign launched through Gmail"); }, onError: () => toast.error("Gmail could not accept the message") });
  const deleteMutation = useMutation({ mutationFn: (target: DeleteTarget) => apiDelete<void>(`/workspace/${target.resource}/${target.id}`), onSuccess: (_, target) => { queryClient.invalidateQueries({ queryKey: [target.resource === "inboxes" ? "inboxes" : target.resource] }); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); setDeleteTarget(null); toast.success(`${target.resource.slice(0, -1)} deleted`); }, onError: (error) => toast.error(mutationErrorMessage(error)) });
  const csvStatusMutation = useMutation({ mutationFn: ({ id, status }: { id: string; status: "running" | "paused" | "stopped" }) => apiPatch<CsvCampaign>(`/csv/campaigns/${id}/status`, { status }), onSuccess: (_, variables) => { queryClient.invalidateQueries({ queryKey: ["csv-campaigns"] }); toast.success(`Campaign ${variables.status}`); }, onError: (error) => toast.error(mutationErrorMessage(error)) });

  const navItems: { id: View; label: string; icon: ReactNode }[] = [
    { id: "dashboard", label: "Dashboard", icon: <LayoutDashboard size={16} /> },
    { id: "campaigns", label: "Campaigns", icon: <Send size={16} /> },
    { id: "recipients", label: "Leads", icon: <Users size={16} /> },
    { id: "inboxes", label: "Inboxes", icon: <InboxIcon size={16} /> },
    { id: "imports", label: "CSV imports", icon: <FileText size={16} /> },
    { id: "templates", label: "Legacy templates", icon: <FileText size={16} /> },
    { id: "history", label: "Activity", icon: <ActivityIcon size={16} /> },
  ];

  const nav = <><div className="mb-8 flex items-center gap-3 px-2" data-testid="brand-lockup"><div className="flex size-8 items-center justify-center rounded-md bg-zinc-950 text-white"><Mail size={16} /></div><div><p className="font-heading text-base font-semibold tracking-tight text-zinc-950" data-testid="brand-name">Mailflow</p><p className="text-[10px] uppercase tracking-[0.12em] text-zinc-400" data-testid="brand-subtitle">Operations</p></div></div><div className="mb-3 px-2 text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-400" data-testid="navigation-label">Workspace</div><nav className="space-y-1" aria-label="Primary navigation">{navItems.map((item) => <button key={item.id} type="button" onClick={() => { setView(item.id); setMobileNav(false); }} className={`flex w-full items-center gap-3 rounded-md px-3 py-2 text-left text-sm transition-colors ${view === item.id ? "bg-zinc-950 font-medium text-white" : "text-zinc-600 hover:bg-zinc-100 hover:text-zinc-950"}`} data-testid={`nav-${item.id}-button`}>{item.icon}<span data-testid={`nav-${item.id}-label`}>{item.label}</span>{item.id === "campaigns" && overview.active_campaigns > 0 ? <span className="ml-auto rounded bg-zinc-800 px-1.5 py-0.5 text-[10px] text-zinc-300" data-testid="active-campaign-count">{overview.active_campaigns}</span> : null}</button>)}</nav><div className="mt-auto border-t border-zinc-200 pt-4"><button type="button" onClick={() => { setView("settings"); setMobileNav(false); }} className={`flex w-full items-center gap-3 rounded-md px-3 py-2 text-sm transition-colors ${view === "settings" ? "bg-zinc-950 font-medium text-white" : "text-zinc-600 hover:bg-zinc-100 hover:text-zinc-950"}`} data-testid="settings-button"><Settings2 size={16} /><span data-testid="settings-label">Workspace settings</span></button></div></>;

  const viewMeta: Record<View, { eyebrow: string; title: string; description: string }> = {
    dashboard: { eyebrow: "Workspace overview", title: "Good morning, Deepanshu", description: "Keep every inbox inside its sending guardrails. Mailflow spaces each message using a server-selected gap." },
    inboxes: { eyebrow: "Connected senders", title: "Inboxes", description: "Connect Gmail accounts and route each campaign through the sender with the right context." },
    recipients: { eyebrow: "Audience", title: "Leads", description: "Keep the people you have permission to contact organized and ready for measured campaigns." },
    campaigns: { eyebrow: "Outbound operations", title: "Campaigns", description: "Schedule exact personalized CSV copy across selected inboxes without rewriting a word." },
    imports: { eyebrow: "Source of truth", title: "CSV imports", description: "Every uploaded row keeps its own independent subjects and bodies for campaign mapping." },
    templates: { eyebrow: "Legacy workflow", title: "Legacy templates", description: "Previous template-based campaigns remain visible, while new campaigns use exact CSV row content." },
    history: { eyebrow: "Audit trail", title: "Send history", description: "Review every message outcome, sender, and campaign in one timestamped log." },
    settings: { eyebrow: "Workspace controls", title: "Settings", description: "Manage sending defaults, provider status, and the operating rules for this workspace." },
  };

  const pageAction = view === "settings" ? null : view === "dashboard" || view === "campaigns" ? <Button onClick={() => { window.location.href = "/campaigns/new"; }} className="gap-2 rounded-md bg-zinc-950 px-4 text-white hover:bg-zinc-800" data-testid="new-campaign-button"><Plus size={15} /> New CSV campaign</Button> : view === "inboxes" ? <div className="flex gap-2"><Button onClick={() => { window.location.href = "/api/oauth/gmail/start"; }} className="gap-2 rounded-md bg-zinc-950 px-4 text-white hover:bg-zinc-800" data-testid="inboxes-connect-gmail-button"><LockKeyhole size={14} /> Connect Gmail</Button><Button onClick={() => setShowInboxForm(true)} variant="outline" className="gap-2 rounded-md" data-testid="add-preview-inbox-button"><Plus size={15} /> Add preview</Button></div> : view === "templates" ? <Button onClick={() => setShowTemplateForm(true)} className="gap-2 rounded-md bg-zinc-950 px-4 text-white hover:bg-zinc-800" data-testid="new-template-button"><Plus size={15} /> New legacy template</Button> : <Button onClick={() => setShowRecipientForm(true)} className="gap-2 rounded-md bg-zinc-950 px-4 text-white hover:bg-zinc-800" data-testid="add-recipient-button"><Plus size={15} /> Add lead</Button>;

  const dashboardView = <>
    <div className="mb-6 grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Sent today" value={String(overview.sent_today)} detail="Across all connected inboxes" icon={<Send size={16} />} accent="bg-emerald-50 text-emerald-700" /><MetricCard label="In queue" value={String(overview.queued)} detail="Messages respecting send gaps" icon={<Clock3 size={16} />} accent="bg-amber-50 text-amber-700" /><MetricCard label="Error rate" value={`${overview.error_rate}%`} detail="Last 24 hours" icon={<CircleAlert size={16} />} accent="bg-zinc-100 text-zinc-700" /><MetricCard label="Active inboxes" value={String(overview.active_inboxes)} detail="Gmail accounts available" icon={<InboxIcon size={16} />} accent="bg-sky-50 text-sky-700" /></div>
    <div className="grid gap-4 xl:grid-cols-[1.35fr_0.65fr]">
      <section className="border border-zinc-200 bg-white" data-testid="active-campaign-panel"><div className="flex items-start justify-between border-b border-zinc-200 p-4"><div><div className="flex items-center gap-2"><span className="size-2 animate-pulse rounded-full bg-emerald-500" data-testid="active-sending-indicator" /><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="active-campaign-title">Active sending</h2></div><p className="mt-1 text-xs text-zinc-500" data-testid="active-campaign-subtitle">One campaign is currently inside its send window</p></div><button type="button" className="rounded-md p-1.5 text-zinc-400 transition-colors hover:bg-zinc-100 hover:text-zinc-800" data-testid="active-campaign-more-button"><MoreHorizontal size={17} /></button></div>{activeCampaign ? <div className="p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-medium text-zinc-900" data-testid="active-campaign-name">{activeCampaign.name}</p><p className="mt-1 text-xs text-zinc-500" data-testid="active-campaign-progress">{activeCampaign.sent_count} of {activeCampaign.total_count} messages sent · {activeCampaign.min_gap_minutes}–{activeCampaign.max_gap_minutes} min gap</p></div><StatusBadge status={activeCampaign.status} /></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-zinc-100" data-testid="campaign-progress-track"><div className="h-full rounded-full bg-emerald-500 transition-[width]" style={{ width: `${Math.min(100, (activeCampaign.sent_count / activeCampaign.total_count) * 100)}%` }} data-testid="campaign-progress-fill" /></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="border border-zinc-200 p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.1em] text-zinc-400" data-testid="next-send-label">Next send</p><p className="mt-2 font-heading text-xl font-semibold text-zinc-950" data-testid="next-send-countdown">{overview.next_send_in_minutes === null ? "—" : `${overview.next_send_in_minutes} min`}</p><p className="mt-1 text-[11px] text-zinc-500" data-testid="next-send-time">{formatDate(activeCampaign.next_send_at)}</p></div><div className="border border-zinc-200 p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.1em] text-zinc-400" data-testid="inbox-route-label">Sending from</p><p className="mt-2 truncate text-sm font-medium text-zinc-900" data-testid="inbox-route-email">{inboxes.find((inbox) => inbox.id === activeCampaign.inbox_id)?.email ?? "Connected inbox"}</p><p className="mt-1 text-[11px] text-zinc-500" data-testid="inbox-route-status">Route is healthy</p></div><div className="border border-zinc-200 p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.1em] text-zinc-400" data-testid="send-rule-label">Send rule</p><p className="mt-2 text-sm font-medium text-zinc-900" data-testid="send-rule-value">Randomized gap</p><p className="mt-1 text-[11px] text-zinc-500" data-testid="send-rule-detail">{activeCampaign.min_gap_minutes} to {activeCampaign.max_gap_minutes} minutes</p></div></div><div className="mt-5 flex flex-wrap gap-2"><Button onClick={() => launchMutation.mutate(activeCampaign.id)} disabled={launchMutation.isPending} variant="outline" size="sm" className="gap-2 rounded-md" data-testid="campaign-send-next-button"><Play size={13} /> {launchMutation.isPending ? "Sending…" : "Send next"}</Button><Button variant="ghost" size="sm" className="gap-2 rounded-md text-zinc-600" data-testid="campaign-pause-button"><Pause size={13} /> Pause campaign</Button></div></div> : <div className="p-4"><EmptyState title="No active campaign" description="Create a campaign to see its queue, send window, and route health here." action={<Button onClick={() => setShowComposer(true)} variant="outline" size="sm" className="mt-4 rounded-md" data-testid="empty-active-campaign-create-button">Create campaign</Button>} /></div>}</section>
      <section className="border border-zinc-200 bg-white" data-testid="activity-panel"><div className="flex items-center justify-between border-b border-zinc-200 p-4"><div><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="activity-title">Live activity</h2><p className="mt-1 text-xs text-zinc-500" data-testid="activity-subtitle">Latest queue events</p></div><span className="text-[11px] font-medium text-emerald-600" data-testid="activity-live-status">Live</span></div><div className="divide-y divide-zinc-100">{overview.recent_activity.length ? overview.recent_activity.map((item: Activity) => <div key={item.id} className="flex gap-3 p-4" data-testid={`activity-item-${item.id}`}><div className={`mt-0.5 flex size-7 shrink-0 items-center justify-center rounded-md ${item.tone === "success" ? "bg-emerald-50 text-emerald-600" : item.tone === "warning" ? "bg-amber-50 text-amber-600" : item.tone === "error" ? "bg-red-50 text-red-600" : "bg-zinc-100 text-zinc-500"}`}><Check size={13} /></div><div className="min-w-0"><p className="text-sm font-medium text-zinc-800" data-testid="activity-message">{item.message}</p><p className="mt-1 truncate text-xs text-zinc-500" data-testid="activity-detail">{item.detail}</p><p className="mt-1 text-[10px] uppercase tracking-[0.08em] text-zinc-400" data-testid="activity-time">{formatDate(item.time)}</p></div></div>) : <div className="p-6"><EmptyState title="No activity yet" description="Queue events will appear here as campaigns run." /></div>}</div></section>
    </div>
    <div className="mt-4 grid gap-4 xl:grid-cols-[1fr_0.7fr]"><section className="border border-zinc-200 bg-white p-4" data-testid="inbox-health-panel"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="inbox-health-title">Inbox health</h2><p className="mt-1 text-xs text-zinc-500" data-testid="inbox-health-subtitle">Every sender stays visible and accountable</p></div><button type="button" onClick={() => setView("inboxes")} className="flex items-center gap-1 text-xs font-medium text-zinc-700 transition-colors hover:text-zinc-950" data-testid="view-all-inboxes-button">View all <ChevronRight size={13} /></button></div>{inboxes.length ? <div className="divide-y divide-zinc-100">{inboxes.slice(0, 3).map((inbox) => <div key={inbox.id} className="flex items-center justify-between gap-3 py-3" data-testid={`inbox-health-row-${inbox.id}`}><div className="flex min-w-0 items-center gap-3"><div className="flex size-8 shrink-0 items-center justify-center rounded-md bg-zinc-100 text-[10px] font-semibold text-zinc-600" data-testid="inbox-initials">{initials(inbox.display_name)}</div><div className="min-w-0"><p className="truncate text-sm font-medium text-zinc-800" data-testid="inbox-health-name">{inbox.display_name}</p><p className="truncate text-xs text-zinc-500" data-testid="inbox-health-email">{inbox.email}</p></div></div><div className="flex shrink-0 items-center gap-2"><StatusBadge status={inbox.status} />{inbox.is_mocked ? <span className="text-[10px] font-semibold uppercase tracking-[0.08em] text-amber-600" data-testid="inbox-mocked-label">MOCKED</span> : null}</div></div>)}</div> : <EmptyState title="No inboxes connected" description="Connect a Gmail account to route campaign messages." />}</section><section className="border border-zinc-200 bg-zinc-950 p-5 text-white" data-testid="guardrails-panel"><div className="flex items-center gap-2"><ShieldCheck size={17} className="text-emerald-400" /><h2 className="font-heading text-lg font-medium tracking-tight" data-testid="guardrails-title">Sending guardrails</h2></div><p className="mt-3 text-sm leading-relaxed text-zinc-400" data-testid="guardrails-description">Mailflow chooses a new delay for every message inside your configured window. No client-side timers, no surprise bursts.</p><div className="mt-5 space-y-3 border-t border-zinc-800 pt-4"><div className="flex items-center justify-between text-xs"><span className="text-zinc-400" data-testid="guardrail-gap-label">Default gap</span><span className="font-medium text-white" data-testid="guardrail-gap-value">10–20 min</span></div><div className="flex items-center justify-between text-xs"><span className="text-zinc-400" data-testid="guardrail-provider-label">Provider</span><span className="font-medium text-white" data-testid="guardrail-provider-value">Gmail API</span></div></div></section></div>
  </>;

  const inboxView = <section className="border border-zinc-200 bg-white" data-testid="inboxes-table-panel"><div className="border-b border-zinc-200 p-4"><div className="flex items-center justify-between"><div><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="inboxes-table-title">Connected inboxes</h2><p className="mt-1 text-xs text-zinc-500" data-testid="inboxes-table-subtitle">OAuth access is stored server-side and never exposed to the browser.</p></div><LockKeyhole size={16} className="text-zinc-400" /></div></div>{inboxes.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm" data-testid="inboxes-table"><thead className="border-b border-zinc-200 bg-zinc-50 text-[10px] uppercase tracking-[0.1em] text-zinc-500"><tr><th className="px-4 py-3 font-semibold">Sender</th><th className="px-4 py-3 font-semibold">Daily limit</th><th className="px-4 py-3 font-semibold">Status</th><th className="px-4 py-3 font-semibold">Connected</th><th className="px-4 py-3" /></tr></thead><tbody className="divide-y divide-zinc-100">{inboxes.map((inbox) => <tr key={inbox.id} className="transition-colors hover:bg-zinc-50/70" data-testid={`inbox-row-${inbox.id}`}><td className="px-4 py-3"><div className="flex items-center gap-3"><div className="flex size-8 items-center justify-center rounded-md bg-zinc-100 text-[10px] font-semibold text-zinc-600">{initials(inbox.display_name)}</div><div><p className="font-medium text-zinc-800" data-testid="inbox-row-name">{inbox.display_name}</p><p className="text-xs text-zinc-500" data-testid="inbox-row-email">{inbox.email}</p></div></div></td><td className="px-4 py-3 text-zinc-600" data-testid="inbox-row-daily-limit">{inbox.daily_sending_limit} / day</td><td className="px-4 py-3"><div className="flex items-center gap-2"><StatusBadge status={inbox.status} />{inbox.is_mocked ? <span className="text-[10px] font-semibold text-amber-600" data-testid="inbox-row-mocked">MOCKED</span> : null}</div></td><td className="px-4 py-3 text-xs text-zinc-500">{formatDate(inbox.connected_at)}</td><td className="px-4 py-3 text-right"><div className="flex justify-end gap-1"><button type="button" onClick={() => setEditingInbox(inbox)} className="rounded-md p-1.5 text-zinc-400 transition-colors hover:bg-zinc-100 hover:text-zinc-700" data-testid={`edit-inbox-${inbox.id}`}><Settings2 size={15} /></button><button type="button" onClick={() => setDeleteTarget({ resource: "inboxes", id: inbox.id, label: inbox.email })} className="rounded-md p-1.5 text-zinc-400 transition-colors hover:bg-red-50 hover:text-red-700" data-testid={`delete-inbox-${inbox.id}`}><Trash2 size={15} /></button></div></td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="Connect your first Gmail inbox" description="Use OAuth to grant send-only access, then route campaigns through it." action={<Button onClick={() => { window.location.href = "/api/oauth/gmail/start"; }} className="mt-4 gap-2 rounded-md bg-zinc-950" data-testid="empty-connect-gmail-button"><LockKeyhole size={14} /> Connect Gmail</Button>} /></div>}</section>;

  const campaignView = <section className="border border-zinc-200 bg-white" data-testid="campaigns-table-panel"><div className="border-b border-zinc-200 p-4"><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="campaigns-table-title">Campaign queue</h2><p className="mt-1 text-xs text-zinc-500" data-testid="campaigns-table-subtitle">Launch, pause, and inspect each send window.</p></div>{campaigns.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm" data-testid="campaigns-table"><thead className="border-b border-zinc-200 bg-zinc-50 text-[10px] uppercase tracking-[0.1em] text-zinc-500"><tr><th className="px-4 py-3 font-semibold">Campaign</th><th className="px-4 py-3 font-semibold">Progress</th><th className="px-4 py-3 font-semibold">Gap</th><th className="px-4 py-3 font-semibold">Next send</th><th className="px-4 py-3 font-semibold">Status</th><th className="px-4 py-3" /></tr></thead><tbody className="divide-y divide-zinc-100">{campaigns.map((campaign) => <tr key={campaign.id} className="transition-colors hover:bg-zinc-50/70" data-testid={`campaign-row-${campaign.id}`}><td className="px-4 py-3"><p className="font-medium text-zinc-800" data-testid="campaign-row-name">{campaign.name}</p><p className="mt-1 text-xs text-zinc-500" data-testid="campaign-row-inbox">{inboxes.find((inbox) => inbox.id === campaign.inbox_id)?.email ?? "Inbox"}</p></td><td className="px-4 py-3 text-xs text-zinc-600">{campaign.sent_count} / {campaign.total_count}</td><td className="px-4 py-3 text-xs text-zinc-600">{campaign.min_gap_minutes}–{campaign.max_gap_minutes}m</td><td className="px-4 py-3 text-xs text-zinc-500">{formatDate(campaign.next_send_at)}</td><td className="px-4 py-3"><StatusBadge status={campaign.status} /></td><td className="px-4 py-3 text-right"><div className="flex justify-end gap-1">{campaign.status !== "completed" ? <button type="button" onClick={() => launchMutation.mutate(campaign.id)} className="rounded-md p-1.5 text-zinc-500 transition-colors hover:bg-zinc-100 hover:text-zinc-900" data-testid={`campaign-launch-${campaign.id}`}><Play size={15} /></button> : <Check size={15} className="text-emerald-600" />}<button type="button" onClick={() => setDeleteTarget({ resource: "campaigns", id: campaign.id, label: campaign.name })} className="rounded-md p-1.5 text-zinc-400 transition-colors hover:bg-red-50 hover:text-red-700" data-testid={`delete-campaign-${campaign.id}`}><Trash2 size={15} /></button></div></td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="No campaigns yet" description="Build a campaign from a template and a connected sender." action={<Button onClick={() => setShowComposer(true)} variant="outline" size="sm" className="mt-4 rounded-md" data-testid="empty-campaign-create-button">Create campaign</Button>} /></div>}</section>;

  const personalizedCampaignView = <div className="space-y-5" data-testid="personalized-campaigns-view"><section className="border border-zinc-200 bg-white" data-testid="csv-campaigns-panel"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-zinc-200 p-4"><div><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="csv-campaigns-title">Personalized CSV campaigns</h2><p className="mt-1 text-xs text-zinc-500" data-testid="csv-campaigns-description">Exact row content, configurable sequence timing, and round-robin inbox allocation.</p></div><span className="rounded-md bg-emerald-50 px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.08em] text-emerald-700" data-testid="exact-copy-badge">No rewriting</span></div>{csvCampaigns.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm" data-testid="csv-campaigns-table"><thead className="border-b border-zinc-200 bg-zinc-50 text-[10px] uppercase tracking-[0.1em] text-zinc-500"><tr><th className="px-4 py-3 font-semibold">Campaign</th><th className="px-4 py-3 font-semibold">Leads</th><th className="px-4 py-3 font-semibold">Sent</th><th className="px-4 py-3 font-semibold">Scheduled</th><th className="px-4 py-3 font-semibold">Failed / skipped</th><th className="px-4 py-3 font-semibold">Status</th><th className="px-4 py-3" /></tr></thead><tbody className="divide-y divide-zinc-100">{csvCampaigns.map((campaign) => <tr key={campaign.id} data-testid={`csv-campaign-row-${campaign.id}`}><td className="px-4 py-3"><button type="button" onClick={() => setActivityCampaign(campaign)} className="text-left" data-testid={`view-csv-campaign-${campaign.id}`}><p className="font-medium text-zinc-900 hover:underline" data-testid="csv-campaign-name">{campaign.name}</p><p className="mt-1 text-xs text-zinc-500" data-testid="csv-campaign-source">{campaign.source_filename} · {campaign.timezone}</p></button></td><td className="px-4 py-3 text-xs text-zinc-600">{campaign.total_leads}</td><td className="px-4 py-3 text-xs text-zinc-600">{campaign.emails_sent}</td><td className="px-4 py-3 text-xs text-zinc-600">{campaign.emails_scheduled}</td><td className="px-4 py-3 text-xs text-zinc-600">{campaign.failed_emails} / {campaign.skipped_leads}</td><td className="px-4 py-3"><StatusBadge status={campaign.status} /></td><td className="px-4 py-3"><div className="flex justify-end gap-1">{campaign.status === "running" ? <button type="button" onClick={() => csvStatusMutation.mutate({ id: campaign.id, status: "paused" })} className="rounded-md p-1.5 text-zinc-500 hover:bg-zinc-100" data-testid={`pause-csv-campaign-${campaign.id}`}><Pause size={14} /></button> : campaign.status === "paused" ? <button type="button" onClick={() => csvStatusMutation.mutate({ id: campaign.id, status: "running" })} className="rounded-md p-1.5 text-zinc-500 hover:bg-zinc-100" data-testid={`resume-csv-campaign-${campaign.id}`}><RotateCcw size={14} /></button> : null}{campaign.status !== "stopped" && campaign.status !== "completed" ? <button type="button" onClick={() => csvStatusMutation.mutate({ id: campaign.id, status: "stopped" })} className="rounded-md p-1.5 text-red-600 hover:bg-red-50" data-testid={`stop-csv-campaign-${campaign.id}`}><X size={14} /></button> : null}</div></td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="No CSV campaigns yet" description="Upload a CSV, map its exact personalized columns, and preview real rows before scheduling." action={<Button onClick={() => { window.location.href = "/campaigns/new"; }} variant="outline" size="sm" className="mt-4 rounded-md" data-testid="empty-csv-campaign-button">Create CSV campaign</Button>} /></div>}</section><div><p className="mb-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-zinc-400" data-testid="legacy-campaigns-label">Legacy template campaigns</p>{campaignView}</div></div>;

  const importsView = <section className="border border-zinc-200 bg-white" data-testid="csv-imports-panel"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-zinc-200 p-4"><div><h2 className="font-heading text-lg font-medium tracking-tight" data-testid="csv-imports-title">Uploaded lead files</h2><p className="mt-1 text-xs text-zinc-500">CSV files are immutable source snapshots so campaign copy cannot change unexpectedly.</p></div><Button onClick={() => { window.location.href = "/campaigns/new"; }} className="gap-2 rounded-md bg-zinc-950 hover:bg-zinc-800" data-testid="upload-new-csv-button"><Plus size={14} /> Upload CSV</Button></div>{csvSources.length ? <div className="divide-y divide-zinc-100">{csvSources.map((source) => <div key={source.id} className="flex flex-wrap items-center justify-between gap-3 p-4" data-testid={`csv-source-row-${source.id}`}><div><p className="text-sm font-medium text-zinc-900" data-testid="csv-source-name">{source.filename}</p><p className="mt-1 text-xs text-zinc-500" data-testid="csv-source-details">{source.row_count} rows · {source.columns.length} columns · Uploaded {formatDate(source.uploaded_at)}</p></div><div className="max-w-md truncate text-[11px] text-zinc-400" data-testid="csv-source-columns">{source.columns.join(" · ")}</div></div>)}</div> : <div className="p-4"><EmptyState title="No CSV files uploaded" description="Start a campaign to upload and map your personalized lead file." /></div>}</section>;

  const recipientsView = <section className="border border-zinc-200 bg-white" data-testid="recipients-table-panel"><div className="border-b border-zinc-200 p-4"><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="recipients-table-title">Recipient list</h2><p className="mt-1 text-xs text-zinc-500" data-testid="recipients-table-subtitle">Only contact people you have permission to email.</p></div>{recipients.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm" data-testid="recipients-table"><thead className="border-b border-zinc-200 bg-zinc-50 text-[10px] uppercase tracking-[0.1em] text-zinc-500"><tr><th className="px-4 py-3 font-semibold">Name</th><th className="px-4 py-3 font-semibold">Email</th><th className="px-4 py-3 font-semibold">Company</th><th className="px-4 py-3 font-semibold">Added</th><th className="px-4 py-3" /></tr></thead><tbody className="divide-y divide-zinc-100">{recipients.map((recipient) => <tr key={recipient.id} className="transition-colors hover:bg-zinc-50/70" data-testid={`recipient-row-${recipient.id}`}><td className="px-4 py-3 font-medium text-zinc-800" data-testid="recipient-row-name">{recipient.name}</td><td className="px-4 py-3 text-xs text-zinc-600" data-testid="recipient-row-email">{recipient.email}</td><td className="px-4 py-3 text-xs text-zinc-600" data-testid="recipient-row-company">{recipient.company || "—"}</td><td className="px-4 py-3 text-xs text-zinc-500">{formatDate(recipient.created_at)}</td><td className="px-4 py-3 text-right"><button type="button" onClick={() => setDeleteTarget({ resource: "recipients", id: recipient.id, label: recipient.email })} className="rounded-md p-1.5 text-zinc-400 transition-colors hover:bg-red-50 hover:text-red-700" data-testid={`delete-recipient-${recipient.id}`}><Trash2 size={15} /></button></td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="No recipients yet" description="Add a recipient before creating a campaign." action={<Button onClick={() => setShowRecipientForm(true)} variant="outline" size="sm" className="mt-4 rounded-md" data-testid="empty-recipient-create-button">Add recipient</Button>} /></div>}</section>;

  const templateView = <section className="grid gap-4 md:grid-cols-2" data-testid="templates-grid">{templates.length ? templates.map((template) => <article key={template.id} className="border border-zinc-200 bg-white p-4" data-testid={`template-card-${template.id}`}><div className="flex items-start justify-between"><div className="flex size-9 items-center justify-center rounded-md bg-zinc-100 text-zinc-600"><FileText size={16} /></div><button type="button" onClick={() => setDeleteTarget({ resource: "templates", id: template.id, label: template.name })} className="rounded-md p-1.5 text-zinc-400 transition-colors hover:bg-red-50 hover:text-red-700" data-testid={`delete-template-${template.id}`}><Trash2 size={15} /></button></div><h2 className="mt-5 text-sm font-medium text-zinc-900" data-testid="template-name">{template.name}</h2><p className="mt-2 text-xs font-medium text-zinc-600" data-testid="template-subject">{template.subject}</p><p className="mt-3 line-clamp-4 whitespace-pre-line text-xs leading-relaxed text-zinc-500" data-testid="template-body">{template.body}</p><div className="mt-4 border-t border-zinc-100 pt-3 text-[10px] uppercase tracking-[0.08em] text-zinc-400" data-testid="template-created">Created {formatDate(template.created_at)}</div></article>) : <div className="md:col-span-2"><EmptyState title="Your template library is empty" description="Save approved copy before launching your first campaign." action={<Button onClick={() => setShowTemplateForm(true)} variant="outline" size="sm" className="mt-4 rounded-md" data-testid="empty-template-create-button">Create template</Button>} /></div>}</section>;

  const historyView = <section className="border border-zinc-200 bg-white" data-testid="history-table-panel"><div className="border-b border-zinc-200 p-4"><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="history-table-title">Message history</h2><p className="mt-1 text-xs text-zinc-500" data-testid="history-table-subtitle">A transparent record of each queued message.</p></div>{history.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm" data-testid="history-table"><thead className="border-b border-zinc-200 bg-zinc-50 text-[10px] uppercase tracking-[0.1em] text-zinc-500"><tr><th className="px-4 py-3 font-semibold">Recipient</th><th className="px-4 py-3 font-semibold">Campaign</th><th className="px-4 py-3 font-semibold">Inbox</th><th className="px-4 py-3 font-semibold">Status</th><th className="px-4 py-3 font-semibold">Sent at</th></tr></thead><tbody className="divide-y divide-zinc-100">{history.map((item) => <tr key={item.id} className="transition-colors hover:bg-zinc-50/70" data-testid={`history-row-${item.id}`}><td className="px-4 py-3 font-medium text-zinc-800" data-testid="history-recipient">{item.recipient_email}</td><td className="px-4 py-3 text-xs text-zinc-600" data-testid="history-campaign">{item.campaign_name}</td><td className="px-4 py-3 text-xs text-zinc-600" data-testid="history-inbox">{item.inbox_email}</td><td className="px-4 py-3"><StatusBadge status={item.status} /></td><td className="px-4 py-3 text-xs text-zinc-500" data-testid="history-sent-at">{formatDate(item.sent_at)}</td></tr>)}</tbody></table></div> : <div className="p-4"><EmptyState title="No messages recorded" description="Your send history will appear here after a campaign is launched." /></div>}</section>;

  const settingsView = <div className="grid gap-4 xl:grid-cols-[1fr_0.7fr]" data-testid="settings-view"><section className="border border-zinc-200 bg-white" data-testid="sending-settings-panel"><div className="border-b border-zinc-200 p-4"><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="sending-settings-title">Sending defaults</h2><p className="mt-1 text-xs leading-relaxed text-zinc-500" data-testid="sending-settings-description">New campaigns start with these values. Each campaign can override them before launch.</p></div><div className="space-y-5 p-4"><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500" data-testid="settings-min-gap-label">Minimum gap (minutes)</span><Input type="number" min="1" value={settingsMinGap} onChange={(event) => setSettingsMinGap(event.target.value)} className="h-10 rounded-md" data-testid="settings-min-gap-input" /></label><label className="block"><span className="mb-2 block text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500" data-testid="settings-max-gap-label">Maximum gap (minutes)</span><Input type="number" min="1" value={settingsMaxGap} onChange={(event) => setSettingsMaxGap(event.target.value)} className="h-10 rounded-md" data-testid="settings-max-gap-input" /></label></div><div className="flex items-center justify-between border-t border-zinc-100 pt-4"><p className="text-xs text-zinc-500" data-testid="settings-save-note">Defaults are stored for this browser preview.</p><Button onClick={() => toast.success("Sending defaults saved")} className="rounded-md bg-zinc-950 hover:bg-zinc-800" data-testid="settings-save-button">Save defaults</Button></div></div></section><section className="border border-zinc-200 bg-white" data-testid="provider-settings-panel"><div className="border-b border-zinc-200 p-4"><h2 className="font-heading text-lg font-medium tracking-tight text-zinc-950" data-testid="provider-settings-title">Provider connection</h2><p className="mt-1 text-xs leading-relaxed text-zinc-500" data-testid="provider-settings-description">Gmail OAuth grants send access without exposing a password to Mailflow.</p></div><div className="space-y-4 p-4"><div className="flex items-start gap-3 border border-emerald-200 bg-emerald-50 p-3"><ShieldCheck size={16} className="mt-0.5 shrink-0 text-emerald-700" /><div><p className="text-sm font-medium text-emerald-900" data-testid="provider-status-title">Gmail OAuth configured</p><p className="mt-1 text-xs leading-relaxed text-emerald-800" data-testid="provider-status-description">Connect each sender from the Inboxes section. Credentials stay server-side.</p></div></div><Button onClick={() => { window.location.href = "/api/oauth/gmail/start"; }} variant="outline" className="w-full gap-2 rounded-md" data-testid="settings-connect-gmail-button"><LockKeyhole size={14} /> Connect another Gmail inbox</Button></div></section></div>;

  const oauthNotice = gmailNotice === "error" ? <div className="mb-5 flex flex-wrap items-center justify-between gap-3 border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800" data-testid="gmail-error-notice"><div><p className="font-medium" data-testid="gmail-error-title">Gmail connection did not finish</p><p className="mt-1 text-xs text-red-700" data-testid="gmail-error-description">Google did not return a usable authorization. Start the connection again and approve the requested Gmail send access.</p></div><Button onClick={() => { window.location.href = "/api/oauth/gmail/start"; }} variant="outline" size="sm" className="rounded-md border-red-200 bg-white text-red-800" data-testid="gmail-retry-button">Try again</Button></div> : gmailNotice === "connected" ? <div className="mb-5 flex items-center gap-2 border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800" data-testid="gmail-success-notice"><Check size={15} /><span data-testid="gmail-success-description">Gmail inbox connected. It is ready for campaigns.</span></div> : null;

  return <div className="min-h-svh bg-[#f4f4f5] text-zinc-950" data-testid="mailflow-app"><aside className="fixed inset-y-0 left-0 z-30 hidden w-60 flex-col border-r border-zinc-200 bg-white p-4 lg:flex" data-testid="desktop-sidebar">{nav}</aside>{mobileNav ? <div className="fixed inset-0 z-40 bg-zinc-950/20 lg:hidden" onClick={() => setMobileNav(false)} data-testid="mobile-nav-overlay"><aside className="flex h-full w-64 flex-col border-r border-zinc-200 bg-white p-4" onClick={(event) => event.stopPropagation()} data-testid="mobile-sidebar">{nav}</aside></div> : null}<main className="lg:pl-60"><header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b border-zinc-200 bg-white px-4 sm:px-6" data-testid="top-header"><div className="flex items-center gap-3"><button type="button" onClick={() => setMobileNav(true)} className="rounded-md p-2 text-zinc-600 hover:bg-zinc-100 lg:hidden" data-testid="mobile-nav-button"><Menu size={18} /></button><div className="hidden items-center gap-2 text-xs text-zinc-400 sm:flex" data-testid="breadcrumb"><span>Workspace</span><ChevronRight size={13} /><span className="font-medium text-zinc-700" data-testid="breadcrumb-current">{viewMeta[view].title}</span></div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 border-r border-zinc-200 pr-3 text-xs text-zinc-500 md:flex" data-testid="workspace-health"><span className="size-1.5 rounded-full bg-emerald-500" /> All systems operational</div><Button onClick={() => { window.location.href = "/api/oauth/gmail/start"; }} variant="outline" size="sm" className="gap-2 rounded-md" data-testid="connect-gmail-button"><LockKeyhole size={13} /> Connect Gmail</Button><div className="flex size-8 items-center justify-center rounded-md bg-zinc-200 text-[10px] font-semibold text-zinc-700" data-testid="user-avatar">DS</div></div></header><div className="mx-auto max-w-[1500px] p-4 sm:p-6"><PageTitle {...viewMeta[view]} action={pageAction} />{oauthNotice}{view === "dashboard" ? dashboardView : view === "inboxes" ? inboxView : view === "recipients" ? recipientsView : view === "campaigns" ? personalizedCampaignView : view === "imports" ? importsView : view === "templates" ? templateView : view === "history" ? historyView : settingsView}</div></main>
    {showComposer ? <CampaignComposer inboxes={inboxes} templates={templates} recipients={recipients} onClose={() => setShowComposer(false)} onSubmit={(payload) => campaignMutation.mutate(payload)} isPending={campaignMutation.isPending} /> : null}
    {showInboxForm ? <SimpleForm title="Add preview inbox" description="Use this for a safe UI walkthrough. Real senders connect with OAuth." onClose={() => setShowInboxForm(false)} onSubmit={(form) => connectMutation.mutate({ email: form.email, display_name: form.name })} submitLabel="Add inbox" fields={[{ key: "name", label: "Display name", placeholder: "Deepanshu" }, { key: "email", label: "Gmail address", placeholder: "deepanshu@gmail.com", type: "email" }]} /> : null}
    {showRecipientForm ? <SimpleForm title="Add recipient" description="Add one contact to your campaign audience." onClose={() => setShowRecipientForm(false)} onSubmit={(form) => recipientMutation.mutate({ name: form.name, email: form.email, company: form.company })} submitLabel="Save recipient" fields={[{ key: "name", label: "Full name", placeholder: "Ari Patel" }, { key: "email", label: "Email address", placeholder: "ari@company.com", type: "email" }, { key: "company", label: "Company", placeholder: "Brightline" }]} /> : null}
    {showTemplateForm ? <SimpleForm title="New template" description="Write approved copy once, then reuse it across campaigns." onClose={() => setShowTemplateForm(false)} onSubmit={(form) => templateMutation.mutate({ name: form.name, subject: form.subject, body: form.body })} submitLabel="Save template" fields={[{ key: "name", label: "Template name", placeholder: "Warm introduction" }, { key: "subject", label: "Subject line", placeholder: "A quick idea for {{company}}" }, { key: "body", label: "Message body", placeholder: "Hi {{first_name}},", textarea: true }]} /> : null}
    {editingInbox ? <SimpleForm title="Inbox settings" description="Set the sender name, optional signature, and daily safety limit." initialValues={{ name: editingInbox.display_name, signature: editingInbox.signature, dailyLimit: String(editingInbox.daily_sending_limit) }} onClose={() => setEditingInbox(null)} onSubmit={(form) => updateInboxMutation.mutate({ id: editingInbox.id, display_name: form.name, signature: form.signature, daily_sending_limit: Number(form.dailyLimit) })} submitLabel="Save inbox" fields={[{ key: "name", label: "Display name", placeholder: "Deepanshu" }, { key: "signature", label: "Signature", placeholder: "Best,\nDeepanshu", textarea: true }, { key: "dailyLimit", label: "Daily sending limit", placeholder: "50", type: "number" }]} /> : null}
    {deleteTarget ? <DeleteConfirm target={deleteTarget} isPending={deleteMutation.isPending} onCancel={() => setDeleteTarget(null)} onConfirm={() => deleteMutation.mutate(deleteTarget)} /> : null}
    {activityCampaign ? <CampaignActivityDrawer campaign={activityCampaign} items={csvActivityQuery.data ?? []} isLoading={csvActivityQuery.isLoading} onClose={() => setActivityCampaign(null)} /> : null}
    <Toaster position="bottom-right" richColors />
  </div>;
}

type FormField = { key: string; label: string; placeholder: string; type?: string; textarea?: boolean };
function SimpleForm({ title, description, fields, submitLabel, initialValues = {}, onClose, onSubmit }: { title: string; description: string; fields: FormField[]; submitLabel: string; initialValues?: Record<string, string>; onClose: () => void; onSubmit: (form: Record<string, string>) => void }) {
  const [form, setForm] = useState<Record<string, string>>(initialValues);
  return <div className="fixed inset-0 z-50 flex items-start justify-end bg-zinc-950/20" data-testid="form-modal-overlay"><div className="h-full w-full max-w-md overflow-y-auto border-l border-zinc-200 bg-white p-5 shadow-xl" data-testid="simple-form-panel"><div className="flex items-start justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-zinc-400" data-testid="form-eyebrow">Workspace</p><h2 className="mt-2 font-heading text-2xl font-semibold tracking-tight text-zinc-950" data-testid="form-title">{title}</h2><p className="mt-2 text-sm leading-relaxed text-zinc-500" data-testid="form-description">{description}</p></div><button type="button" onClick={onClose} className="rounded-md p-2 text-zinc-400 hover:bg-zinc-100" data-testid="form-close-button"><X size={17} /></button></div><div className="mt-8 space-y-4">{fields.map((field) => <label key={field.key} className="block" data-testid={`form-field-${field.key}`}><span className="mb-2 block text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500" data-testid={`form-label-${field.key}`}>{field.label}</span>{field.textarea ? <textarea value={form[field.key] ?? ""} onChange={(event) => setForm({ ...form, [field.key]: event.target.value })} placeholder={field.placeholder} className="min-h-32 w-full rounded-md border border-zinc-200 px-3 py-2 text-sm outline-none transition-[border-color,box-shadow] placeholder:text-zinc-400 focus:border-zinc-900 focus:ring-2 focus:ring-zinc-900/10" data-testid={`form-input-${field.key}`} /> : <Input type={field.type ?? "text"} value={form[field.key] ?? ""} onChange={(event) => setForm({ ...form, [field.key]: event.target.value })} placeholder={field.placeholder} className="h-10 rounded-md" data-testid={`form-input-${field.key}`} />}</label>)}</div><div className="mt-8 flex justify-end gap-2 border-t border-zinc-200 pt-4"><Button type="button" variant="ghost" onClick={onClose} className="rounded-md" data-testid="form-cancel-button">Cancel</Button><Button type="button" onClick={() => onSubmit(form)} className="rounded-md bg-zinc-950 px-4 hover:bg-zinc-800" data-testid="form-submit-button">{submitLabel}</Button></div></div></div>;
}

function DeleteConfirm({ target, isPending, onCancel, onConfirm }: { target: DeleteTarget; isPending: boolean; onCancel: () => void; onConfirm: () => void }) {
  return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-zinc-950/30 p-4" data-testid="delete-confirmation-overlay"><div className="w-full max-w-sm border border-zinc-200 bg-white p-5 shadow-xl" data-testid="delete-confirmation-dialog"><div className="flex size-10 items-center justify-center rounded-md bg-red-50 text-red-700"><Trash2 size={18} /></div><h2 className="mt-4 font-heading text-xl font-semibold tracking-tight text-zinc-950" data-testid="delete-confirmation-title">Delete {target.label}?</h2><p className="mt-2 text-sm leading-relaxed text-zinc-500" data-testid="delete-confirmation-description">This action cannot be undone. If this record is used by a campaign, Mailflow will keep it and explain what needs to change first.</p><div className="mt-6 flex justify-end gap-2"><Button type="button" variant="ghost" onClick={onCancel} className="rounded-md" data-testid="delete-cancel-button">Cancel</Button><Button type="button" onClick={onConfirm} disabled={isPending} className="gap-2 rounded-md bg-red-700 text-white hover:bg-red-800" data-testid="delete-confirm-button"><Trash2 size={14} /> {isPending ? "Deleting…" : "Delete"}</Button></div></div></div>;
}

function CampaignActivityDrawer({ campaign, items, isLoading, onClose }: { campaign: CsvCampaign; items: ScheduledEmail[]; isLoading: boolean; onClose: () => void }) {
  const leadGroups = items.reduce<Record<string, ScheduledEmail[]>>((groups, item) => {
    groups[item.recipient_email] = [...(groups[item.recipient_email] ?? []), item];
    return groups;
  }, {});
  return <div className="fixed inset-0 z-50 flex justify-end bg-zinc-950/25" data-testid="campaign-activity-overlay"><aside className="h-full w-full max-w-xl overflow-y-auto border-l border-zinc-200 bg-white shadow-xl" data-testid="campaign-activity-drawer"><div className="sticky top-0 z-10 flex items-start justify-between border-b border-zinc-200 bg-white p-5"><div><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-zinc-400">Lead activity</p><h2 className="mt-2 font-heading text-2xl font-semibold tracking-tight" data-testid="campaign-activity-title">{campaign.name}</h2><p className="mt-1 text-xs text-zinc-500" data-testid="campaign-activity-summary">{campaign.source_filename} · {isLoading ? "Loading activity…" : `${Object.keys(leadGroups).length} scheduled leads`}</p><a href={`/api/csv/campaigns/${campaign.id}/export`} className="mt-3 inline-flex items-center rounded-md border border-zinc-200 px-3 py-1.5 text-xs font-medium text-zinc-700 transition-colors hover:bg-zinc-50" data-testid="download-campaign-status-link">Download status CSV</a></div><button type="button" onClick={onClose} className="rounded-md p-2 text-zinc-400 hover:bg-zinc-100" data-testid="campaign-activity-close-button"><X size={17} /></button></div><div className="space-y-4 p-5">{isLoading ? <div className="min-h-40 animate-pulse bg-zinc-100" data-testid="campaign-activity-loading" /> : Object.entries(leadGroups).length ? Object.entries(leadGroups).map(([email, events]) => <article key={email} className="border border-zinc-200 p-4" data-testid={`lead-activity-${email}`}><div><p className="text-sm font-medium text-zinc-900" data-testid="lead-activity-name">{events[0]?.first_name || email}{events[0]?.company ? ` — ${events[0].company}` : ""}</p><p className="mt-1 text-xs text-zinc-500" data-testid="lead-activity-email">{email}</p></div><div className="mt-4 space-y-3 border-l border-zinc-200 pl-4">{events.map((event) => <div key={event.id} className="relative" data-testid={`lead-event-${event.id}`}><span className={`absolute -left-[21px] top-1.5 size-2 rounded-full ${event.status === "sent" ? "bg-emerald-500" : event.status === "failed" ? "bg-red-500" : "bg-amber-500"}`} /><div className="flex items-center justify-between gap-3"><p className="text-xs font-medium text-zinc-800" data-testid="lead-event-label">{event.step_label}</p><StatusBadge status={event.status} /></div><p className="mt-1 text-[11px] text-zinc-500" data-testid="lead-event-time">{event.status === "sent" ? `Sent ${formatDate(event.sent_at)}` : `Scheduled ${formatDate(event.scheduled_at)}`}</p><p className="mt-1 truncate text-[11px] text-zinc-400" data-testid="lead-event-subject">{event.subject}</p>{event.error ? <p className="mt-1 text-[11px] text-red-600" data-testid="lead-event-error">{event.error}</p> : null}</div>)}</div></article>) : <EmptyState title="No scheduled lead activity" description="Launch this draft campaign to create its exact row-level delivery timeline." />}</div></aside></div>;
}

function CampaignComposer({ inboxes, templates, recipients, onClose, onSubmit, isPending }: { inboxes: Inbox[]; templates: Template[]; recipients: Recipient[]; onClose: () => void; onSubmit: (payload: { name: string; inbox_id: string; template_id: string; recipient_ids: string[]; min_gap_minutes: number; max_gap_minutes: number }) => void; isPending: boolean }) {
  const [name, setName] = useState("New outreach campaign");
  const [inboxId, setInboxId] = useState(inboxes[0]?.id ?? "");
  const [templateId, setTemplateId] = useState(templates[0]?.id ?? "");
  const [selected, setSelected] = useState<string[]>(recipients.slice(0, 5).map((recipient) => recipient.id));
  const [minGap, setMinGap] = useState("10");
  const [maxGap, setMaxGap] = useState("20");
  const selectedLabel = useMemo(() => `${selected.length} recipient${selected.length === 1 ? "" : "s"} selected`, [selected.length]);
  const toggleRecipient = (id: string) => setSelected((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  return <div className="fixed inset-0 z-50 flex items-start justify-end bg-zinc-950/20" data-testid="campaign-composer-overlay"><div className="flex h-full w-full max-w-lg flex-col overflow-hidden border-l border-zinc-200 bg-white p-5 shadow-xl" data-testid="campaign-composer-panel"><div className="flex items-start justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-zinc-400" data-testid="composer-eyebrow">Campaign builder</p><h2 className="mt-2 font-heading text-2xl font-semibold tracking-tight text-zinc-950" data-testid="composer-title">New campaign</h2><p className="mt-2 text-sm leading-relaxed text-zinc-500" data-testid="composer-description">Choose a sender, approved copy, and a transparent delay range.</p></div><button type="button" onClick={onClose} className="rounded-md p-2 text-zinc-400 hover:bg-zinc-100" data-testid="composer-close-button"><X size={17} /></button></div><div className="mt-7 flex-1 space-y-5 overflow-y-auto pb-8"><label className="block"><span className="mb-2 block text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500">Campaign name</span><Input value={name} onChange={(event) => setName(event.target.value)} className="h-10 rounded-md" data-testid="campaign-name-input" /></label><label className="block"><span className="mb-2 block text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500">Sending inbox</span><select value={inboxId} onChange={(event) => setInboxId(event.target.value)} className="h-10 w-full rounded-md border border-zinc-200 bg-white px-3 text-sm outline-none focus:border-zinc-900 focus:ring-2 focus:ring-zinc-900/10" data-testid="campaign-inbox-select">{inboxes.map((inbox) => <option key={inbox.id} value={inbox.id}>{inbox.email}{inbox.is_mocked ? " · MOCKED" : ""}</option>)}</select></label><label className="block"><span className="mb-2 block text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500">Message template</span><select value={templateId} onChange={(event) => setTemplateId(event.target.value)} className="h-10 w-full rounded-md border border-zinc-200 bg-white px-3 text-sm outline-none focus:border-zinc-900 focus:ring-2 focus:ring-zinc-900/10" data-testid="campaign-template-select">{templates.map((template) => <option key={template.id} value={template.id}>{template.name}</option>)}</select></label><div><div className="mb-2 flex items-center justify-between"><span className="text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500">Recipients</span><span className="text-xs text-zinc-500" data-testid="selected-recipient-count">{selectedLabel}</span></div><div className="max-h-44 divide-y divide-zinc-100 overflow-y-auto rounded-md border border-zinc-200">{recipients.length ? recipients.map((recipient) => <label key={recipient.id} className="flex cursor-pointer items-center gap-3 px-3 py-2.5 transition-colors hover:bg-zinc-50" data-testid={`recipient-option-${recipient.id}`}><input type="checkbox" checked={selected.includes(recipient.id)} onChange={() => toggleRecipient(recipient.id)} className="size-4 accent-zinc-900" data-testid={`recipient-checkbox-${recipient.id}`} /><span className="min-w-0"><span className="block text-sm font-medium text-zinc-800">{recipient.name}</span><span className="block truncate text-xs text-zinc-500">{recipient.email}</span></span></label>) : <p className="p-4 text-xs text-zinc-500" data-testid="no-recipient-options">Add recipients before building a campaign.</p>}</div></div><div><div className="mb-2 flex items-center gap-2"><span className="text-[11px] font-semibold uppercase tracking-[0.08em] text-zinc-500">Random gap</span><span className="rounded bg-amber-50 px-2 py-1 text-[10px] font-medium text-amber-700" data-testid="gap-preview-badge">Per message</span></div><div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2"><Input type="number" min="1" value={minGap} onChange={(event) => setMinGap(event.target.value)} className="h-10 rounded-md" data-testid="min-gap-input" /><span className="text-sm text-zinc-400">to</span><Input type="number" min="1" value={maxGap} onChange={(event) => setMaxGap(event.target.value)} className="h-10 rounded-md" data-testid="max-gap-input" /></div><p className="mt-2 text-xs leading-relaxed text-zinc-500" data-testid="gap-helper-text">System will randomize the delay between these values to keep sends measured and predictable.</p></div></div><div className="sticky bottom-0 mt-0 flex items-center justify-between border-t border-zinc-200 bg-white pt-4"><p className="text-xs text-zinc-500" data-testid="composer-footer-note"><ShieldCheck size={13} className="mr-1 inline text-emerald-600" /> Send rules are server-controlled</p><div className="flex gap-2"><Button type="button" variant="ghost" onClick={onClose} className="rounded-md" data-testid="composer-cancel-button">Cancel</Button><Button type="button" disabled={isPending || !inboxId || !templateId || selected.length === 0} onClick={() => onSubmit({ name, inbox_id: inboxId, template_id: templateId, recipient_ids: selected, min_gap_minutes: Number(minGap), max_gap_minutes: Number(maxGap) })} className="gap-2 rounded-md bg-zinc-950 px-4 hover:bg-zinc-800" data-testid="campaign-create-submit-button"><Send size={14} /> {isPending ? "Queueing…" : "Queue campaign"}</Button></div></div></div></div>;
}
